/**
 * Asset registry. `stackup/*` is synced from the portfolio's public
 * folder (scripts/sync-assets.mjs); `film-assets/*` is generated by
 * scripts/prepare-assets.py.
 *
 * Poses prefixed `kit-` come from the flattened asset-kit sheet and are
 * PLACEHOLDERS (~250px source). Swap the file for a hi-res original and
 * nothing else needs to change.
 */
import { staticFile } from "remotion";

export const screen = (name: string) => staticFile(`stackup/${name}.webp`);
export const stackup = (name: string) => staticFile(`stackup/${name}.webp`);
export const filmAsset = (name: string) => staticFile(`film-assets/${name}.png`);

/** Screen image size (bezel included). */
export const SCREEN_W = 1312;
export const SCREEN_H = 2656;

export type PoseName =
  | "laptop" | "leaning" | "phone-notebook" | "arms-crossed"
  | "kit-thinking" | "kit-working" | "kit-phone" | "kit-confused"
  | "kit-realisation" | "kit-comparing" | "kit-confident";

/**
 * h = PNG height; head = approx. head width in PNG px. Characters are
 * normalised so every pose shows the same head size on screen — the
 * person never changes scale when a pose swaps.
 */
export const POSES: Record<PoseName, { file: string; h: number; head: number; hiRes: boolean }> = {
  laptop: { file: "pose-laptop", h: 662, head: 185, hiRes: true },
  leaning: { file: "pose-leaning", h: 692, head: 200, hiRes: true },
  "phone-notebook": { file: "pose-phone-notebook", h: 784, head: 165, hiRes: true },
  "arms-crossed": { file: "pose-arms-crossed", h: 718, head: 170, hiRes: true },
  "kit-thinking": { file: "kit-thinking", h: 640, head: 200, hiRes: false },
  "kit-working": { file: "kit-working", h: 394, head: 140, hiRes: false },
  "kit-phone": { file: "kit-phone", h: 398, head: 150, hiRes: false },
  "kit-confused": { file: "kit-confused", h: 410, head: 150, hiRes: false },
  "kit-realisation": { file: "kit-realisation", h: 448, head: 150, hiRes: false },
  "kit-comparing": { file: "kit-comparing", h: 456, head: 150, hiRes: false },
  "kit-confident": { file: "kit-confident", h: 456, head: 140, hiRes: false },
};

/** On-screen head width at scale 1. */
export const HEAD_PX = 120;
